  'diff': '{\n  "name": "Diff",\n  "version": "1.0.0",\n  "fileTypes": ["diff", "patch"],\n  "scopeName": "source.diff",\n  "patterns": [\n    { "include": "#header" },\n    { "include": "#hunk" },\n    { "include": "#addition" },\n    { "include": "#deletion" }\n  ],\n  "repository": {\n    "header": {\n      "patterns": [\n        {\n          "name": "meta.diff.range.normal",\n          "match": "^(@@).*(@@).*\$",\n          "captures": {\n            "1": { "name": "punctuation.definition.range.diff" },\n            "2": { "name": "punctuation.definition.range.diff" }\n          }\n        },\n        {\n          "name": "meta.diff.header",\n          "match": "^(---|\\\\+\\\\+\\\\+|\\\\*\\\\*\\\\*).*\$",\n          "captures": {\n            "1": { "name": "meta.toc-list.banner.normal.diff" }\n          }\n        },\n        {\n          "name": "meta.diff.header.from-file",\n          "match": "^(From|Index):.*\$"\n        }\n      ]\n    },\n    "hunk": {\n      "patterns": [\n        {\n          "name": "punctuation.definition.range.diff",\n          "match": "^@@.*@@\$"\n        }\n      ]\n    },\n    "addition": {\n      "patterns": [\n        {\n          "name": "markup.inserted.diff",\n          "match": "^\\\\+.*\$"\n        }\n      ]\n    },\n    "deletion": {\n      "patterns": [\n        {\n          "name": "markup.deleted.diff",\n          "match": "^-.*\$"\n        }\n      ]\n    }\n  }\n}\n',
